    # Seed routes with far/heavy customers, then greedily fill by best insertion.
    while unassigned:
        seed = unassigned.pop(0)
        route = [seed]
        load = d(seed)

        improved = True
        while improved:
            improved = False
            best = None
            best_idx = -1
            best_pos = 0

            for idx in range(len(unassigned)):
                node = unassigned[idx]
                if load + d(node) > capacity:
                    continue
                best_local_cost = None
                best_local_pos = 0
                for pos in range(len(route) + 1):
                    cst = insertion_cost(route, node, pos)
                    if best_local_cost is None or cst < best_local_cost or (cst == best_local_cost and pos < best_local_pos):
                        best_local_cost = cst
                        best_local_pos = pos
                key = (best_local_cost, dist[depot][node], -d(node), node)
                if best is None or key < best:
                    best = key
                    best_idx = idx
                    best_pos = best_local_pos

            if best_idx >= 0:
                node = unassigned.pop(best_idx)
                route.insert(best_pos, node)
                load += d(node)
                improved = True

        routes.append(route)

    # Repair loop: ensure every customer appears exactly once.
    seen = {}
    for r in routes:
        for x in r:
            seen[x] = seen.get(x, 0) + 1

    missing = []
    for c in customers:
        if c not in seen:
            missing.append(c)

    for node in missing:
        best_r = -1
        best_pos = 0
        best_cost = None
        for ri in range(len(routes)):
            r = routes[ri]
            if route_load(r) + d(node) > capacity:
                continue
            for pos in range(len(r) + 1):
                cst = insertion_cost(r, node, pos)
                if best_cost is None or cst < best_cost or (cst == best_cost and (ri, pos) < (best_r, best_pos)):
                    best_cost = cst
                    best_r = ri
                    best_pos = pos
        if best_r == -1:
            routes.append([node])
        else:
            routes[best_r].insert(best_pos, node)

    # Remove duplicates if any and repair deterministically.
    seen_count = {}
    for r in routes:
        for x in r:
            seen_count[x] = seen_count.get(x, 0) + 1

    if len(seen_count) != len(customers):
        counts = {}
        cleaned = []
        for r in routes:
            nr = []
            load = 0
            for x in r:
                if counts.get(x, 0) == 0:
                    nr.append(x)
                    counts[x] = 1
                    load += d(x)
            cleaned.append(nr)
        routes = cleaned
        missing = []
        for c in customers:
            if counts.get(c, 0) == 0:
                missing.append(c)
        for node in missing:
            best_r = -1
            best_pos = 0
            best_cost = None
            for ri in range(len(routes)):
                r = routes[ri]
                if route_load(r) + d(node) > capacity:
                    continue
                for pos in range(len(r) + 1):
                    cst = insertion_cost(r, node, pos)
                    if best_cost is None or cst < best_cost:
                        best_cost = cst
                        best_r = ri
                        best_pos = pos
            if best_r == -1:
                routes.append([node])
            else:
                routes[best_r].insert(best_pos, node)

    # Intra-route 2-opt.
    for ri in range(len(routes)):
        r = routes[ri]
        if len(r) < 4:
            continue
        changed = True
        while changed:
            changed = False
            m = len(r)
            for i in range(m - 2):
                a = depot if i == 0 else r[i - 1]
                b = r[i]
                for j in range(i + 2, m):
                    c = r[j - 1]
                    d2 = depot if j == m else r[j]
                    old = dist[a][b] + dist[c][d2]
                    new = dist[a][c] + dist[b][d2]
                    if new < old:
                        r[i:j] = r[i:j][::-1]
                        changed = True
                        break
                if changed:
                    break
        routes[ri] = r

    # Inter-route relocate improvement.
    improved = True
    while improved:
        improved = False
        best_move = None
        best_delta = 0
        route_loads = []
        for r in routes:
            route_loads.append(route_load(r))

        for i in range(len(routes)):
            ri = routes[i]
            for p in range(len(ri)):
                node = ri[p]
                left = depot if p == 0 else ri[p - 1]
                right = depot if p + 1 == len(ri) else ri[p + 1]
                remove_delta = dist[left][right] - dist[left][node] - dist[node][right]
                for j in range(len(routes)):
                    if i == j:
                        continue
                    rj = routes[j]
                    if route_loads[j] + d(node) > capacity:
                        continue
                    for q in range(len(rj) + 1):
                        prev = depot if q == 0 else rj[q - 1]
                        nxt = depot if q == len(rj) else rj[q]
                        add_delta = dist[prev][node] + dist[node][nxt] - dist[prev][nxt]
                        delta = remove_delta + add_delta
                        if delta < best_delta:
                            best_delta = delta
                            best_move = (i, p, j, q)
        if best_move is not None:
            i, p, j, q = best_move
            node = routes[i].pop(p)
            if i == j and p < q:
                q -= 1
            routes[j].insert(q, node)
            improved = True

    # Final cleanup: drop empty routes, keep all customers once.
    final_routes = []
    seen = {}
    for r in routes:
        if r:
            nr = []
            for x in r:
                if seen.get(x, 0) == 0:
                    nr.append(x)
                    seen[x] = 1
            if nr:
                final_routes.append(nr)

    for c in customers:
        if seen.get(c, 0) == 0:
            best_r = -1
            best_pos = 0
            best_cost = None
            for ri in range(len(final_routes)):
                r = final_routes[ri]
                if route_load(r) + d(c) > capacity:
                    continue
                for pos in range(len(r) + 1):
                    cst = insertion_cost(r, c, pos)
                    if best_cost is None or cst < best_cost:
                        best_cost = cst
                        best_r = ri
                        best_pos = pos
            if best_r == -1:
                final_routes.append([c])
            else:
                final_routes[best_r].insert(best_pos, c)

    return final_routes
